def count_nested(n):
    total = 0
    for i in range(n):
        for j in range(n):
            total += 1
    return total

def count_single(n):
    total = 0
    for i in range(n):
        total += 1
    return total

for n in (10, 100):
    print(n, count_nested(n), count_single(n))
